export const isRedirectAllowed = (url: string) => {
  let allowed = false
  for (const allowedUrl of redirectAllowlist) {
    allowed = allowed || url.includes(escapeHTML(allowedUrl))
  }
  return allowed
}

const escapeHTML = str => {
  return str.replace(/[&<>'"]/g,
    tag => {
      return ({
        '&': '&amp;',
        '<': '&lt;',
        '>': '&gt;',
        "'": '&#39;',
        '"': '&quot;'
      }[tag])
    })
}

